 def test_qualification_02_approval_and_revocation_survive_navigation_and_reload(self):
  self.basic();p=self.page;p.evaluate('''()=>{let s=JSON.parse(localStorage.getItem('arenaPathway.v2')),a=s.profiles[0];a.ageYears=16;a.ageReviewedAt=new Date().toISOString();a.recruiting.rulesReview={acknowledged:true,sport:a.sport,at:new Date().toISOString()};localStorage.setItem('arenaPathway.v2',JSON.stringify(s));}''');p.goto(base.base.BASE+'/recruiting');p.wait_for_selector('#recruiting-profile-builder',state='attached');nav=p.get_by_role('navigation',name='Recruiting journey',exact=True);nav.get_by_role('button',name='2 · Build athlete information',exact=True).click();p.get_by_label('Include identity',exact=True).check();nav.get_by_role('button',name='3 · Build and preview',exact=True).click();p.get_by_role('button',name='Parent approve local preview',exact=True).click()
  for _ in range(2):
   nav.get_by_role('button',name='1 · Choose schools',exact=True).click();nav.get_by_role('button',name='3 · Build and preview',exact=True).click();self.assertTrue(self.state()['profiles'][0]['recruiting']['parentApproved']);self.assertEqual(p.locator('.coach-card-status').inner_text(),'Parent-approved local preview')
  p.reload();p.wait_for_selector('#recruiting-profile-builder',state='attached');nav=p.get_by_role('navigation',name='Recruiting journey',exact=True);nav.get_by_role('button',name='3 · Build and preview',exact=True).click();p.get_by_role('button',name='Revoke preview approval',exact=True).click()
  for _ in range(2):
   nav.get_by_role('button',name='1 · Choose schools',exact=True).click();nav.get_by_role('button',name='3 · Build and preview',exact=True).click();self.assertFalse(self.state()['profiles'][0]['recruiting']['parentApproved']);self.assertEqual(p.locator('.coach-card-status').inner_text(),'Draft · not parent-approved')
  p.reload();p.wait_for_selector('#recruiting-profile-builder',state='attached');p.get_by_role('navigation',name='Recruiting journey',exact=True).get_by_role('button',name='3 · Build and preview',exact=True).click();self.assertEqual(p.locator('.coach-card-status').inner_text(),'Draft · not parent-approved')
 def test_qualification_03_pillar_labels_fit_their_active_touch_targets(self):
  p=self.page;measurements=[]
  for width,height in [(1440,900),(810,1080),(390,844)]:
   p.set_viewport_size({'width':width,'height':height})
   for path in ['/my-pathway?view=family','/my-ap','/recruiting','/locked-in-demo']:
    p.goto(base.base.BASE+path);p.wait_for_load_state('networkidle');nav=p.get_by_role('navigation',name='Primary navigation',exact=True);self.assertEqual(nav.locator('a').all_text_contents(),['Profile','SIEM','Recruiting','LockedIn'])
    for link in nav.locator('a').all():
     box=link.bounding_box();self.assertGreaterEqual(box['height'],44);self.assertLessEqual(link.evaluate('(e)=>e.scrollWidth'),box['width']+1);fit=link.evaluate('(e)=>{const range=document.createRange();range.selectNodeContents(e);const text=range.getBoundingClientRect(),box=e.getBoundingClientRect();return text.left>=box.left-1&&text.right<=box.right+1}');self.assertTrue(fit,link.inner_text()+str(width));measurements.append({'path':path,'width':width,'label':link.inner_text(),'targetWidth':box['width'],'height':box['height'],'textFits':fit})
    self.assertFalse(p.evaluate('document.documentElement.scrollWidth>innerWidth+1'))
  (OUT.parent/(base.base.ENGINE+'-nav-measurements.json')).write_text(json.dumps(measurements,indent=2)+'\n')
